import Foundation

/// Indoor layout of HSL stations and terminals, generated by tools/stations/build_stations.py
/// from OpenStreetMap + Digitransit and bundled with the app (App/Resources/Stations/stations.json).
public struct StationMap: Codable, Sendable {
    public var version: Int
    public var generated: String?
    public var attribution: String?
    public var stations: [Station]

    public static func decode(_ data: Data) throws -> StationMap {
        try JSONDecoder().decode(StationMap.self, from: data)
    }

    /// The station that serves this GTFS stop (platform), if mapped.
    public func station(servingStop stopId: String) -> Station? {
        stations.first { s in s.stops.contains { $0.id == stopId } }
    }

    /// Nearest station within `meters`.
    public func station(near p: GeoPoint, within meters: Double = 250) -> Station? {
        stations
            .map { ($0, $0.centerPoint.distance(to: p)) }
            .filter { $0.1 <= meters }
            .min { $0.1 < $1.1 }?.0
    }
}

public struct Station: Codable, Sendable, Identifiable {
    public enum Kind: String, Codable, Sendable { case metro, train, bus }
    public enum Status: String, Codable, Sendable { case complete, partial, empty }

    public struct Entrance: Codable, Sendable, Identifiable {
        public var id: String
        public var pos: [Double]
        public var level: Double
        public var name: String?
        public var ref: String?
        public var wheelchair: String?
        public var graphNode: Int?
        public var point: GeoPoint { GeoPoint(latitude: pos[0], longitude: pos[1]) }
    }

    public struct Platform: Codable, Sendable, Identifiable {
        public var id: String
        public var ref: String?
        public var level: Double
        public var line: [[Double]]
        public var gtfsStops: [String]
        public var points: [GeoPoint] { line.map { GeoPoint(latitude: $0[0], longitude: $0[1]) } }
    }

    public struct Connector: Codable, Sendable, Identifiable {
        public var id: String
        /// "escalator", "stairs", "elevator"
        public var kind: String
        public var levels: [Double]
        public var line: [[Double]]
        public var conveying: String?
    }

    public struct Stop: Codable, Sendable {
        public var id: String
        public var code: String?
        public var platform: String?
        public var pos: [Double]
    }

    public struct Node: Codable, Sendable {
        public var point: GeoPoint
        public var level: Double?

        public init(from decoder: Decoder) throws {
            var c = try decoder.unkeyedContainer()
            let lat = try c.decode(Double.self), lon = try c.decode(Double.self)
            point = GeoPoint(latitude: lat, longitude: lon)
            level = try c.decodeIfPresent(Double.self)
        }

        public func encode(to encoder: Encoder) throws {
            var c = encoder.unkeyedContainer()
            try c.encode(point.latitude)
            try c.encode(point.longitude)
            try c.encode(level)
        }
    }

    public struct Edge: Codable, Sendable {
        public enum Kind: String, Codable, Sendable { case walk, stairs, escalator, elevator, platform }
        public var a: Int
        public var b: Int
        public var length: Double
        public var kind: Kind
        /// +1 only a→b, −1 only b→a (one-way escalators), 0 both ways.
        public var direction: Int

        public init(from decoder: Decoder) throws {
            var c = try decoder.unkeyedContainer()
            a = try c.decode(Int.self)
            b = try c.decode(Int.self)
            length = try c.decode(Double.self)
            kind = Kind(rawValue: try c.decode(String.self)) ?? .walk
            direction = (try? c.decode(Int.self)) ?? 0
        }

        public func encode(to encoder: Encoder) throws {
            var c = encoder.unkeyedContainer()
            try c.encode(a); try c.encode(b); try c.encode(length); try c.encode(kind.rawValue); try c.encode(direction)
        }
    }

    public struct Graph: Codable, Sendable {
        public var nodes: [Node]
        public var edges: [Edge]
    }

    public var id: String
    public var name: String
    public var kind: Kind
    public var center: [Double]
    public var levels: [Double]
    public var status: Status
    public var score: Double
    public var entrances: [Entrance]
    public var platforms: [Platform]
    public var connectors: [Connector]
    public var graph: Graph
    public var stops: [Stop]
    public var missing: [String]

    public var centerPoint: GeoPoint { GeoPoint(latitude: center[0], longitude: center[1]) }

    /// The platform serving a GTFS stop.
    public func platform(forStop stopId: String) -> Platform? {
        platforms.first { $0.gtfsStops.contains(stopId) }
    }
}

// MARK: - Routing inside a station

public struct StationRoute: Sendable {
    public struct Step: Sendable, Equatable {
        public var kind: Station.Edge.Kind
        public var distance: Double
        public var fromLevel: Double?
        public var toLevel: Double?
        /// "Take the escalator down to level -1"
        public var instruction: String
    }

    public var nodes: [Int]
    public var points: [GeoPoint]
    public var seconds: TimeInterval
    public var distance: Double
    public var steps: [Step]
}

public struct StationRouter: Sendable {
    public var walkingSpeed: Double
    /// Avoid stairs and escalators (lifts only).
    public var stepFree: Bool

    public init(walkingSpeed: Double = 1.35, stepFree: Bool = false) {
        self.walkingSpeed = walkingSpeed
        self.stepFree = stepFree
    }

    func cost(_ e: Station.Edge) -> Double? {
        let v = max(walkingSpeed, 0.5)
        switch e.kind {
        case .walk, .platform: return e.length / v
        case .stairs: return stepFree ? nil : e.length / (v * 0.55)
        case .escalator: return stepFree ? nil : e.length / (0.5 + v * 0.35)  // ride + a little walking
        case .elevator: return 35 + e.length / 1.0                             // waiting dominates
        }
    }

    /// Fastest route from a graph node to any of the target nodes (Dijkstra).
    public func route(in station: Station, from start: Int, to targets: Set<Int>) -> StationRoute? {
        let g = station.graph
        guard g.nodes.indices.contains(start), !targets.isEmpty else { return nil }
        var adj = [[(to: Int, edge: Int)]](repeating: [], count: g.nodes.count)
        for (i, e) in g.edges.enumerated() where g.nodes.indices.contains(e.a) && g.nodes.indices.contains(e.b) {
            if e.direction >= 0 { adj[e.a].append((e.b, i)) }
            if e.direction <= 0 { adj[e.b].append((e.a, i)) }
        }
        var dist = [Double](repeating: .infinity, count: g.nodes.count)
        var prev = [(node: Int, edge: Int)?](repeating: nil, count: g.nodes.count)
        var done = [Bool](repeating: false, count: g.nodes.count)
        dist[start] = 0
        // Small graphs (a few thousand nodes): a linear-scan Dijkstra is fine and dependency-free.
        var frontier: Set<Int> = [start]
        var reached: Int?
        while let u = frontier.min(by: { dist[$0] < dist[$1] }) {
            frontier.remove(u)
            if done[u] { continue }
            done[u] = true
            if targets.contains(u) { reached = u; break }
            for (v, ei) in adj[u] where !done[v] {
                guard let c = cost(g.edges[ei]) else { continue }
                let nd = dist[u] + c
                if nd < dist[v] {
                    dist[v] = nd
                    prev[v] = (u, ei)
                    frontier.insert(v)
                }
            }
        }
        guard let end = reached else { return nil }

        var nodes = [end]
        var edges: [Int] = []
        var cur = end
        while let p = prev[cur] {
            nodes.append(p.node)
            edges.append(p.edge)
            cur = p.node
        }
        nodes.reverse()
        edges.reverse()
        let steps = describe(station: station, nodes: nodes, edges: edges)
        return StationRoute(nodes: nodes, points: nodes.map { g.nodes[$0].point }, seconds: dist[end],
                            distance: edges.reduce(0) { $0 + g.edges[$1].length }, steps: steps)
    }

    /// From an entrance to the platform serving `stopId`.
    public func route(in station: Station, fromEntrance entrance: Station.Entrance, toStop stopId: String) -> StationRoute? {
        guard let start = entrance.graphNode ?? nearestNode(in: station, to: entrance.point, level: entrance.level),
              let platform = station.platform(forStop: stopId) else { return nil }
        return route(in: station, from: start, to: platformNodes(in: station, platform))
    }

    /// Graph nodes on (or right next to) a platform.
    public func platformNodes(in station: Station, _ p: Station.Platform, tolerance: Double = 15) -> Set<Int> {
        let pts = p.points
        var out = Set<Int>()
        for (i, n) in station.graph.nodes.enumerated() where n.level == nil || n.level == p.level {
            let d = pts.count == 1 ? pts[0].distance(to: n.point) : Polyline(pts).project(n.point)?.lateralDistance ?? .infinity
            if d <= tolerance { out.insert(i) }
        }
        return out
    }

    /// Nearest graph node, preferring the given level.
    public func nearestNode(in station: Station, to p: GeoPoint, level: Double? = nil) -> Int? {
        station.graph.nodes.indices.min { a, b in
            score(station.graph.nodes[a], p, level) < score(station.graph.nodes[b], p, level)
        }
    }

    private func score(_ n: Station.Node, _ p: GeoPoint, _ level: Double?) -> Double {
        let off = (level != nil && n.level != nil && n.level != level) ? 1_000.0 : 0
        return n.point.distance(to: p) + off
    }

    /// Merges consecutive edges of the same kind into plain-language steps.
    func describe(station: Station, nodes: [Int], edges: [Int]) -> [StationRoute.Step] {
        let g = station.graph
        var steps: [StationRoute.Step] = []
        for (k, ei) in edges.enumerated() {
            let e = g.edges[ei]
            let kind: Station.Edge.Kind = e.kind == .platform ? .walk : e.kind
            let from = g.nodes[nodes[k]].level, to = g.nodes[nodes[k + 1]].level
            if var last = steps.last, last.kind == kind {
                last.distance += e.length
                last.toLevel = to ?? last.toLevel
                steps[steps.count - 1] = last
            } else {
                steps.append(.init(kind: kind, distance: e.length, fromLevel: from, toLevel: to, instruction: ""))
            }
        }
        return steps.map { s in
            var s = s
            s.instruction = Self.instruction(for: s)
            return s
        }
    }

    static func instruction(for s: StationRoute.Step) -> String {
        let m = "\(Int(s.distance.rounded())) m"
        func levelName(_ l: Double?) -> String {
            guard let l else { return "the next level" }
            if l == 0 { return "street level" }
            return l < 0 ? "level \(Int(l))" : "floor \(Int(l))"
        }
        let dir: String = {
            guard let a = s.fromLevel, let b = s.toLevel, a != b else { return "" }
            return b < a ? " down" : " up"
        }()
        switch s.kind {
        case .walk, .platform: return "Walk \(m)"
        case .escalator: return "Take the escalator\(dir) to \(levelName(s.toLevel))"
        case .stairs: return "Take the stairs\(dir) to \(levelName(s.toLevel))"
        case .elevator: return "Take the lift\(dir) to \(levelName(s.toLevel))"
        }
    }
}
